using Microsoft.AspNetCore.Mvc;
using ModelBindingValidation.Models;

namespace ModelBindingValidation.Controllers
{
    public class HomeController : Controller
    {
        public IActionResult FromFormExample() => View();

        [HttpPost]
        public IActionResult FromFormExample([FromForm] Employee model)
        {
            ViewBag.Message = "Employee data received";
            return View(model);
        }
    }
}

using Microsoft.AspNetCore.Mvc;
using ModelBindingValidation.Models;

namespace ModelBindingValidation.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class EmployeesApiController : ControllerBase
    {
        [HttpPost]
        public IActionResult Create([FromBody] Employee model)
        {
            if (!ModelState.IsValid)
                return BadRequest(ModelState);
            return Ok(new { message = "Received", model.Name, model.Id });
        }
    }
}

public class ProductsController : Controller
{
    private readonly IRepository repository;

    public ProductsController(IRepository repo)
    {
        repository = repo;
    }

    // Route: /Products/Search/1?term=laptop&page=2
    // Default: id=1 from route, but [FromQuery] overrides it
    public IActionResult Search([FromQuery] int id, string term, int page)
    {
        // id will be 0 here — the query string has no 'id' key
        // 'term' comes from query string: ?term=laptop
        var results = repository.Search(term, page);
        return View(results);
    }
}

public class ProductsController : Controller
{
    // Route: [HttpGet("products/{id}")]
    [HttpGet("products/{id}")]
    public IActionResult Details([FromRoute] int id)
    {
        var product = repository.GetById(id);
        if (product == null)
            return NotFound();
        return View(product);
    }
}

using Microsoft.AspNetCore.Mvc;

public class ApiController : ControllerBase
{
    // Call with: curl -H "X-API-Key: abc123" https://localhost/api/check-key
    [HttpGet("check-key")]
    public IActionResult CheckKey([FromHeader(Name = "X-API-Key")] string apiKey)
    {
        if (apiKey != "abc123")
            return Unauthorized();
        return Ok("API key is valid");
    }
}

using Microsoft.AspNetCore.Mvc;

namespace ModelBindingValidation.Models
{
    public class RequestHeaders
    {
        [FromHeader]
        public string Accept { get; set; }

        [FromHeader(Name = "Accept-Encoding")]
        public string AcceptEncoding { get; set; }

        [FromHeader(Name = "Accept-Language")]
        public string AcceptLanguage { get; set; }

        [FromHeader(Name = "User-Agent")]
        public string UserAgent { get; set; }

        [FromHeader(Name = "X-Forwarded-For")]
        public string ForwardedFor { get; set; }
    }
}

public IActionResult InspectHeaders(RequestHeaders headers)
{
    return View(headers);
}
